<?php
declare(strict_types=1);
use Illuminate\Support\Facades\Route;use Plugins\Modules\Phonetics\Http\Controllers\PhoneticsAdminController;use Plugins\Modules\Phonetics\Http\Controllers\PhoneticsPracticeController;
Route::middleware(['web','installed','plugin:phonetics'])->prefix('courses/{courseSlug}/phonetics-practice')->name('plugins.phonetics.practice.')->group(function():void{Route::get('/',[PhoneticsPracticeController::class,'index'])->name('index');Route::post('/attempts',[PhoneticsPracticeController::class,'storeAttempt'])->middleware(['auth','throttle:30,1'])->name('attempts.store');});
Route::middleware(['web','installed','auth','plugin:phonetics','permission:phonetics.manage'])->prefix('admin/phonetics')->name('plugins.phonetics.admin.')->group(function():void{Route::get('/',[PhoneticsAdminController::class,'index'])->name('index');Route::get('/learning',[PhoneticsLearningAdminController::class,'index'])->name('learning');Route::get('/learning/lessons',[PhoneticsLearningAdminController::class,'lessons'])->name('learning.lessons');Route::post('/learning/assignments',[PhoneticsLearningAdminController::class,'storeAssignment'])->name('learning.assignments.store');Route::delete('/learning/assignments/{assignment}',[PhoneticsLearningAdminController::class,'destroyAssignment'])->name('learning.assignments.destroy');Route::post('/learning/exams',[PhoneticsLearningAdminController::class,'storeExam'])->name('learning.exams.store');Route::patch('/learning/exams/{exam}/status',[PhoneticsLearningAdminController::class,'updateExamStatus'])->name('learning.exams.status');Route::patch('/settings',[PhoneticsAdminController::class,'updateSettings'])->name('settings');Route::post('/',[PhoneticsAdminController::class,'store'])->name('store');Route::put('/{entry}',[PhoneticsAdminController::class,'update'])->name('update');Route::delete('/{entry}',[PhoneticsAdminController::class,'destroy'])->name('destroy');});